<script setup lang="ts">
import InlineMarkup from './InlineMarkup'
import {sessionUi as ui,appController as c} from '../../stores/session-ui'
function close(){(document.getElementById('trash-dialog') as HTMLDialogElement).close()}
function backdrop(e:Event){if(e.target===e.currentTarget)close()}
</script><template><dialog id="trash-dialog" class="app-dialog" aria-labelledby="trash-title" @click="backdrop"><div class="trash-panel"><div class="modal-head"><div><h2 id="trash-title">回收站</h2><p id="trash-sub">{{ui.trashSub || '删除的会话文件保留在磁盘上，可以恢复或彻底清除'}}</p></div><button type="button" class="modal-close" id="trash-close" title="关闭" aria-label="关闭" @click="close">×</button></div><div id="trash-note" role="status" aria-live="polite" :class="{err:ui.trashError}">{{ui.trashNote}}</div><div id="trash-list" class="trash-list" @click="c?.trashItemAction"><div v-if="!ui.trash.length" class="trash-empty">{{ui.trashEmpty}}</div><div v-for="it in ui.trash" :key="it.id" class="trash-item" :data-id="it.id"><div class="trash-main"><div class="trash-title"><InlineMarkup v-if="it.icon" :html="it.icon"/><span>{{it.title}}</span></div><div class="trash-meta"><span>{{it.when}} 删除</span><span>{{it.sizeLabel}}</span><span class="trash-cwd" :title="it.cwd">{{it.directory}}</span></div><div class="trash-origin" :class="{warn:!it.restorable}" :title="it.restorable?it.origin:undefined">{{it.restorable?'恢复到 '+it.originLabel:it.reason || '无法恢复'}}</div></div><div class="trash-acts"><button type="button" class="btn" data-act="restore" :disabled="!it.restorable || ui.trashPending===it.id+':restore'">恢复</button><button type="button" class="btn danger" data-act="purge" :disabled="ui.trashPending===it.id+':purge'">彻底删除</button></div></div></div><div class="modal-actions"><button type="button" class="btn" id="trash-reload" @click="c?.loadTrash()">刷新</button><button type="button" class="btn danger" id="trash-purge-all" :disabled="ui.trashDisabled || ui.trashPending==='all'" @click="c?.purgeAllTrash()">清空回收站</button><button type="button" class="btn go" id="trash-done" @click="close">完成</button></div></div></dialog></template>